#!/bin/sh
# Hand the approved queue to the press dispatcher.
echo "enqueue press queue at $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
python3 - <<'PY'
from itertools import permutations
jobs = ["J-401","J-415","J-402","J-409","J-418","J-407"]
nums = {j:int(j[2:]) for j in jobs}
solutions = []
for perm in permutations(jobs):
    if not all(nums[a] < nums[b] for a,b in zip(perm, perm[1:])):
        continue
    if perm.index("J-418") > perm.index("J-402"):
        continue
    solutions.append(perm)
print("strict-increasing AND 418-ahead-of-402 satisfying orders:", len(solutions))
for s in solutions:
    print(" ->", " ".join(s))
PY
